interface Coffee { int cost(); }
class SimpleCoffee implements Coffee {
    public int cost() { return 10; }
}
abstract class CoffeeDecorator implements Coffee {
    protected Coffee coffee;
    CoffeeDecorator(Coffee c) { this.coffee = c; }
}
class Milk extends CoffeeDecorator {
    Milk(Coffee c) { super(c); }
    public int cost() { return coffee.cost() + 5; }
}
class Sugar extends CoffeeDecorator {
    Sugar(Coffee c) { super(c); }
    public int cost() { return coffee.cost() + 2; }
}
public class Main {
    public static void main(String[] args) {
        Coffee c = new Sugar(new Milk(new SimpleCoffee()));
        System.out.println(c.cost());
    }
}

import java.util.*;
interface Observer { void update(String msg); }
class Subject {
    private List<Observer> list = new ArrayList<>();
    void attach(Observer o) { list.add(o); }
    void notifyAllObservers(String msg) {
        for (Observer o : list) o.update(msg);
    }
}
public class ObserverTest {
    public static void main(String[] args) {
        Subject s = new Subject();
        s.attach(msg -> System.out.print("O1:" + msg + " "));
        s.attach(msg -> System.out.print("O2:" + msg + " "));
        s.notifyAllObservers("News");
    }
}

interface ModernPrinter { void printDocument(String text); }
class LegacyPrinter {
    void printOldFormat(String text) { System.out.print("Legacy: " + text); }
}
class PrinterAdapter implements ModernPrinter {
    private LegacyPrinter legacy;
    PrinterAdapter(LegacyPrinter l) { this.legacy = l; }
    public void printDocument(String text) { legacy.printOldFormat(text); }
}
public class Main {
    public static void main(String[] args) {
        ModernPrinter printer = new PrinterAdapter(new LegacyPrinter());
        printer.printDocument("Hello");
    }
}

import java.util.*;
interface Component { int getSize(); }
class FileLeaf implements Component {
    int size;
    FileLeaf(int s) { this.size = s; }
    public int getSize() { return size; }
}
class FolderComposite implements Component {
    List<Component> children = new ArrayList<>();
    void add(Component c) { children.add(c); }
    public int getSize() {
        int total = 0;
        for (Component c : children) total += c.getSize();
        return total;
    }
}
public class Main {
    public static void main(String[] args) {
        FolderComposite root = new FolderComposite();
        root.add(new FileLeaf(10));
        FolderComposite sub = new FolderComposite();
        sub.add(new FileLeaf(20));
        sub.add(new FileLeaf(30));
        root.add(sub);
        System.out.println(root.getSize());
    }
}

