class Query {
    private String table;
    private String where;
    public static class Builder {
        private Query q = new Query();
        public Builder from(String t) { q.table = t; return this; }
        public Builder where(String w) { q.where = w; return this; }
        public Query build() { return q; }
    }
    public String toString() { return "SELECT * FROM " + table + " WHERE " + where; }
}
public class Main {
    public static void main(String[] args) {
        Query q = new Query.Builder().from("Users").where("age > 18").build();
        System.out.println(q);
    }
}

